CREATE TABLE owner_scope(slot INTEGER PRIMARY KEY CHECK(slot=1),owner BLOB NOT NULL);
CREATE TABLE vaults(owner BLOB NOT NULL,id BLOB NOT NULL CHECK(length(id)=16), operation BLOB NOT NULL CHECK(length(operation)=16), header TEXT NOT NULL,cleanup_budget INTEGER NOT NULL DEFAULT 1 CHECK(cleanup_budget>=0),PRIMARY KEY(owner,id));
CREATE TABLE upload_outcomes(owner BLOB NOT NULL,upload BLOB NOT NULL CHECK(length(upload)=16),digest BLOB NOT NULL CHECK(length(digest)=32),result TEXT NOT NULL,expires INTEGER NOT NULL,PRIMARY KEY(owner,upload));
CREATE TABLE global_settings(key TEXT PRIMARY KEY NOT NULL,value TEXT NOT NULL);
CREATE TABLE key_flights(owner BLOB NOT NULL,vault BLOB NOT NULL CHECK(length(vault)=16),token INTEGER NOT NULL,day INTEGER NOT NULL,reserved INTEGER NOT NULL,actual INTEGER,created INTEGER NOT NULL,settled INTEGER,payment INTEGER NOT NULL DEFAULT 0,phase TEXT NOT NULL DEFAULT 'reserved',in_flight INTEGER NOT NULL DEFAULT 1,generation INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(owner,token));
CREATE INDEX key_flights_day ON key_flights(day,settled);
CREATE TABLE operations(owner BLOB NOT NULL,operation BLOB NOT NULL CHECK(length(operation)=16),digest BLOB NOT NULL CHECK(length(digest)=32),result BLOB,expires INTEGER NOT NULL,token INTEGER NOT NULL,runtime INTEGER NOT NULL,admission INTEGER NOT NULL DEFAULT 0 CHECK(admission IN (0,1,2,3)),PRIMARY KEY(owner,operation));
CREATE INDEX operations_expiry ON operations(expires,owner);
CREATE UNIQUE INDEX vault_creation_operation ON vaults(owner,operation);
CREATE TRIGGER IF NOT EXISTS key_pool_insert_size BEFORE INSERT ON key_flights
WHEN (84+length(NEW.owner)+length(NEW.vault)+length(CAST(NEW.phase AS BLOB)))>256 OR length(NEW.owner)>29 OR length(CAST(NEW.phase AS BLOB))>32
BEGIN SELECT RAISE(ABORT,'key row capacity'); END;
CREATE TRIGGER IF NOT EXISTS key_pool_update_size BEFORE UPDATE ON key_flights
WHEN (84+length(NEW.owner)+length(NEW.vault)+length(CAST(NEW.phase AS BLOB)))>256 OR length(NEW.owner)>29 OR length(CAST(NEW.phase AS BLOB))>32
BEGIN SELECT RAISE(ABORT,'key row capacity'); END;
CREATE TRIGGER IF NOT EXISTS key_pool_count BEFORE INSERT ON key_flights
WHEN NOT EXISTS(SELECT 1 FROM key_flights WHERE owner=NEW.owner AND token=NEW.token)
AND (SELECT count(*) FROM key_flights WHERE owner=NEW.owner)>=512
BEGIN SELECT RAISE(ABORT,'key row count capacity'); END;
CREATE TABLE revisions(owner BLOB NOT NULL,vault BLOB NOT NULL, object BLOB NOT NULL, revision INTEGER NOT NULL, born INTEGER NOT NULL, retired INTEGER, plain_size INTEGER NOT NULL, manifest BLOB NOT NULL, hashes TEXT NOT NULL, deleted INTEGER NOT NULL, charge INTEGER NOT NULL, PRIMARY KEY(owner,vault,object,revision));
CREATE INDEX revision_sequence ON revisions(owner,vault,born,retired);
CREATE TABLE objects(owner BLOB NOT NULL,vault BLOB NOT NULL, object BLOB NOT NULL, head INTEGER NOT NULL,purged INTEGER NOT NULL DEFAULT 0 CHECK(purged IN (0,1)), PRIMARY KEY(owner,vault,object));
CREATE TABLE uploads(owner BLOB NOT NULL,id BLOB NOT NULL, vault BLOB NOT NULL, object BLOB NOT NULL, expected INTEGER NOT NULL, expires INTEGER NOT NULL, digest BLOB NOT NULL, request TEXT NOT NULL, reserved INTEGER NOT NULL,receipt_budget INTEGER NOT NULL,cleanup_budget INTEGER NOT NULL CHECK(cleanup_budget>=0),cancel_job BLOB,PRIMARY KEY(owner,id));
CREATE UNIQUE INDEX one_upload_per_vault ON uploads(owner,vault);
CREATE TABLE chunks(owner BLOB NOT NULL,upload BLOB NOT NULL, idx INTEGER NOT NULL, data BLOB NOT NULL, PRIMARY KEY(owner,upload,idx));
CREATE TABLE revision_chunks(owner BLOB NOT NULL,vault BLOB NOT NULL, object BLOB NOT NULL, revision INTEGER NOT NULL, idx INTEGER NOT NULL, data BLOB NOT NULL, PRIMARY KEY(owner,vault,object,revision,idx));
CREATE UNIQUE INDEX vault_global_id ON vaults(id);
CREATE TABLE vault_members(owner BLOB NOT NULL, vault BLOB NOT NULL CHECK(length(vault)=16), member BLOB NOT NULL CHECK(length(member) BETWEEN 1 AND 29 AND member!=owner), role INTEGER NOT NULL CHECK(role IN (1,2)), PRIMARY KEY(owner,vault,member));
CREATE INDEX vault_member_access ON vault_members(member,vault);
CREATE TABLE shared_upload_handles(owner BLOB NOT NULL, vault BLOB NOT NULL CHECK(length(vault)=16), upload BLOB NOT NULL CHECK(length(upload)=16), caller BLOB NOT NULL CHECK(length(caller) BETWEEN 1 AND 29), wire BLOB NOT NULL CHECK(length(wire)=16), PRIMARY KEY(owner,vault));
CREATE TRIGGER shared_upload_cleanup AFTER DELETE ON uploads BEGIN DELETE FROM shared_upload_handles WHERE owner=OLD.owner AND vault=OLD.vault AND upload=OLD.id; END;
CREATE INDEX upload_outcomes_global_expiry ON upload_outcomes(expires,owner);
CREATE INDEX uploads_global_expiry ON uploads(expires,owner);
CREATE INDEX revisions_global_retired ON revisions(retired,owner) WHERE retired IS NOT NULL;
CREATE TABLE IF NOT EXISTS accounts(owner TEXT PRIMARY KEY NOT NULL,balance_cycles INTEGER NOT NULL CHECK(balance_cycles>=0),storage_bytes INTEGER NOT NULL DEFAULT 0,storage_charged_at_ms INTEGER NOT NULL,storage_charge_remainder INTEGER NOT NULL DEFAULT 0 CHECK(storage_charge_remainder>=0 AND storage_charge_remainder<1073741824000));
CREATE TABLE IF NOT EXISTS vault_cycle_reservations(owner TEXT NOT NULL,token TEXT NOT NULL,reserved INTEGER NOT NULL,actual INTEGER,created_at_ms INTEGER NOT NULL,settled_at_ms INTEGER,in_flight INTEGER NOT NULL DEFAULT 1,generation INTEGER NOT NULL DEFAULT 0,execution_checkpoint INTEGER NOT NULL DEFAULT 0,execution_billed INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(owner,token));
CREATE TABLE IF NOT EXISTS vault_storage_billing_state(slot INTEGER PRIMARY KEY CHECK(slot=1),cursor_owner TEXT NOT NULL,billing_now_ms INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payments(wallet TEXT NOT NULL,operation BLOB NOT NULL,record TEXT NOT NULL,expires INTEGER NOT NULL,PRIMARY KEY(wallet,operation));
CREATE INDEX IF NOT EXISTS payments_expiry ON payments(expires);
CREATE TABLE IF NOT EXISTS account_ledger(id INTEGER PRIMARY KEY AUTOINCREMENT,owner TEXT NOT NULL,kind TEXT NOT NULL,amount_cycles INTEGER NOT NULL,balance_after INTEGER NOT NULL,at_ms INTEGER NOT NULL,operation BLOB);
CREATE INDEX IF NOT EXISTS account_ledger_owner ON account_ledger(owner,id);
CREATE TABLE IF NOT EXISTS quote_fee_flights(wallet TEXT NOT NULL,operation BLOB NOT NULL,token INTEGER NOT NULL,generation INTEGER NOT NULL,expires_ns INTEGER NOT NULL,record TEXT NOT NULL,PRIMARY KEY(wallet,operation));
CREATE INDEX uploads_expiry ON uploads(owner,expires);
CREATE INDEX operations_owner_expiry ON operations(owner,expires);
CREATE INDEX upload_outcomes_owner_expiry ON upload_outcomes(owner,expires,upload);
CREATE INDEX payments_wallet_expiry ON payments(wallet,expires);
CREATE INDEX payments_link_challenge ON payments(json_extract(record,'$.bridge_v1.Link.challenge.challenge')) WHERE json_type(record,'$.bridge_v1.Link.challenge.challenge')='array';
CREATE INDEX key_flights_active ON key_flights(owner) WHERE in_flight=1;
CREATE INDEX key_flights_gc_global ON key_flights(settled,owner,token) WHERE in_flight=0 AND phase!='cancelled' AND settled IS NOT NULL;
CREATE INDEX key_flights_gc_owner ON key_flights(owner,settled,token) WHERE in_flight=0 AND phase!='cancelled' AND settled IS NOT NULL;
CREATE INDEX key_flights_settled ON key_flights(settled) WHERE in_flight=0;
CREATE INDEX vault_cycle_reservations_gc ON vault_cycle_reservations(settled_at_ms) WHERE in_flight=0 AND execution_billed>=execution_checkpoint AND settled_at_ms IS NOT NULL;
CREATE TABLE payment_completion_reservations(wallet TEXT NOT NULL,operation BLOB NOT NULL,spare BLOB NOT NULL CHECK(length(spare)=1048576),PRIMARY KEY(wallet,operation),FOREIGN KEY(wallet,operation) REFERENCES payments(wallet,operation) ON DELETE CASCADE);
CREATE TRIGGER payment_completion_delete AFTER DELETE ON payments BEGIN DELETE FROM payment_completion_reservations WHERE wallet=OLD.wallet AND operation=OLD.operation; END;
CREATE TABLE payment_scan_slots(slot INTEGER PRIMARY KEY CHECK(slot BETWEEN 1 AND 8),record TEXT NOT NULL CHECK(length(record)=512));
CREATE TABLE payment_holds(kind TEXT NOT NULL,bucket TEXT NOT NULL,total INTEGER NOT NULL CHECK(typeof(total)='integer' AND total>=0),PRIMARY KEY(kind,bucket));
CREATE TRIGGER IF NOT EXISTS accounting_accounts_INSERT_size BEFORE INSERT ON accounts WHEN (4+length(CAST(NEW.owner AS BLOB))+32)>512 OR length(CAST(NEW.owner AS BLOB))>63 BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_accounts_UPDATE_size BEFORE UPDATE ON accounts WHEN (4+length(CAST(NEW.owner AS BLOB))+32)>512 OR length(CAST(NEW.owner AS BLOB))>63 BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_payments_INSERT_size BEFORE INSERT ON payments WHEN (4+length(CAST(NEW.wallet AS BLOB))+4+length(CAST(NEW.operation AS BLOB))+4+length(CAST(NEW.record AS BLOB))+8)>4096 OR length(NEW.operation)<>16 OR length(CAST(NEW.wallet AS BLOB))>63 BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_payments_UPDATE_size BEFORE UPDATE ON payments WHEN (4+length(CAST(NEW.wallet AS BLOB))+4+length(CAST(NEW.operation AS BLOB))+4+length(CAST(NEW.record AS BLOB))+8)>4096 OR length(NEW.operation)<>16 OR length(CAST(NEW.wallet AS BLOB))>63 BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_quote_fee_flights_INSERT_size BEFORE INSERT ON quote_fee_flights WHEN (4+length(CAST(NEW.wallet AS BLOB))+4+length(CAST(NEW.operation AS BLOB))+4+length(CAST(NEW.record AS BLOB))+24)>4096 OR length(NEW.operation)<>16 OR length(CAST(NEW.wallet AS BLOB))>63 BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_quote_fee_flights_UPDATE_size BEFORE UPDATE ON quote_fee_flights WHEN (4+length(CAST(NEW.wallet AS BLOB))+4+length(CAST(NEW.operation AS BLOB))+4+length(CAST(NEW.record AS BLOB))+24)>4096 OR length(NEW.operation)<>16 OR length(CAST(NEW.wallet AS BLOB))>63 BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_quote_fee_flights_count BEFORE INSERT ON quote_fee_flights WHEN NOT EXISTS(SELECT 1 FROM quote_fee_flights WHERE wallet=NEW.wallet AND operation=NEW.operation) AND (SELECT count(*) FROM quote_fee_flights)>=8  BEGIN SELECT RAISE(ABORT,'accounting count capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_vault_cycle_reservations_INSERT_size BEFORE INSERT ON vault_cycle_reservations WHEN (4+length(CAST(NEW.owner AS BLOB))+4+length(CAST(NEW.token AS BLOB))+64)>512 OR length(CAST(NEW.owner AS BLOB))>63 OR length(CAST(NEW.token AS BLOB))>128 OR length(NEW.token)=0 BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_vault_cycle_reservations_UPDATE_size BEFORE UPDATE ON vault_cycle_reservations WHEN (4+length(CAST(NEW.owner AS BLOB))+4+length(CAST(NEW.token AS BLOB))+64)>512 OR length(CAST(NEW.owner AS BLOB))>63 OR length(CAST(NEW.token AS BLOB))>128 OR length(NEW.token)=0 BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_account_ledger_INSERT_size BEFORE INSERT ON account_ledger WHEN (4+length(CAST(NEW.owner AS BLOB))+4+length(CAST(NEW.kind AS BLOB))+4+length(CAST(NEW.operation AS BLOB))+32)>512 OR length(CAST(NEW.owner AS BLOB))>63 OR length(CAST(NEW.kind AS BLOB))>32 OR length(NEW.operation)>16 BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_account_ledger_UPDATE_size BEFORE UPDATE ON account_ledger WHEN (4+length(CAST(NEW.owner AS BLOB))+4+length(CAST(NEW.kind AS BLOB))+4+length(CAST(NEW.operation AS BLOB))+32)>512 OR length(CAST(NEW.owner AS BLOB))>63 OR length(CAST(NEW.kind AS BLOB))>32 OR length(NEW.operation)>16 BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_global_settings_INSERT_size BEFORE INSERT ON global_settings WHEN (4+length(CAST(NEW.key AS BLOB))+4+length(CAST(NEW.value AS BLOB))+0)>8192  BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_global_settings_UPDATE_size BEFORE UPDATE ON global_settings WHEN (4+length(CAST(NEW.key AS BLOB))+4+length(CAST(NEW.value AS BLOB))+0)>8192  BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_global_settings_count BEFORE INSERT ON global_settings WHEN NOT EXISTS(SELECT 1 FROM global_settings WHERE key=NEW.key) AND (SELECT count(*) FROM global_settings)>=7  BEGIN SELECT RAISE(ABORT,'accounting count capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_vault_storage_billing_state_INSERT_size BEFORE INSERT ON vault_storage_billing_state WHEN (4+length(CAST(NEW.cursor_owner AS BLOB))+16)>512 OR length(CAST(NEW.cursor_owner AS BLOB))>63 BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_vault_storage_billing_state_UPDATE_size BEFORE UPDATE ON vault_storage_billing_state WHEN (4+length(CAST(NEW.cursor_owner AS BLOB))+16)>512 OR length(CAST(NEW.cursor_owner AS BLOB))>63 BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TABLE initial_cycle_grants(principal TEXT PRIMARY KEY NOT NULL,database_id TEXT NOT NULL,grant_cycles INTEGER NOT NULL CHECK(grant_cycles>=0),created_at_ms INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS accounting_initial_cycle_grants_INSERT_size BEFORE INSERT ON initial_cycle_grants WHEN (4+length(CAST(NEW.principal AS BLOB))+4+length(CAST(NEW.database_id AS BLOB))+16)>128 OR length(CAST(NEW.principal AS BLOB))>63 OR length(CAST(NEW.database_id AS BLOB))>5 BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_initial_cycle_grants_UPDATE_size BEFORE UPDATE ON initial_cycle_grants WHEN (4+length(CAST(NEW.principal AS BLOB))+4+length(CAST(NEW.database_id AS BLOB))+16)>128 OR length(CAST(NEW.principal AS BLOB))>63 OR length(CAST(NEW.database_id AS BLOB))>5 BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_initial_cycle_grants_count BEFORE INSERT ON initial_cycle_grants WHEN NOT EXISTS(SELECT 1 FROM initial_cycle_grants WHERE principal=NEW.principal) AND (SELECT count(*) FROM initial_cycle_grants)>=16384  BEGIN SELECT RAISE(ABORT,'accounting count capacity'); END;
CREATE TABLE key_subsidies(owner TEXT PRIMARY KEY NOT NULL,state INTEGER NOT NULL DEFAULT 0 CHECK(state IN (0,1,2)),token TEXT,attached INTEGER NOT NULL DEFAULT 0 CHECK(attached>=0 AND attached<=30000000000),actual INTEGER CHECK(actual>=0 AND actual<=attached),CHECK(state=0 OR token IS NOT NULL),CHECK(state<>2 OR (actual IS NOT NULL AND actual>0)));
CREATE TRIGGER IF NOT EXISTS accounting_key_subsidies_INSERT_size BEFORE INSERT ON key_subsidies WHEN (4+length(CAST(NEW.owner AS BLOB))+4+length(CAST(NEW.token AS BLOB))+24)>256 OR length(CAST(NEW.owner AS BLOB))>63 OR length(CAST(NEW.token AS BLOB))>128 BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_key_subsidies_UPDATE_size BEFORE UPDATE ON key_subsidies WHEN (4+length(CAST(NEW.owner AS BLOB))+4+length(CAST(NEW.token AS BLOB))+24)>256 OR length(CAST(NEW.owner AS BLOB))>63 OR length(CAST(NEW.token AS BLOB))>128 BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_key_subsidies_count BEFORE INSERT ON key_subsidies WHEN NOT EXISTS(SELECT 1 FROM key_subsidies WHERE owner=NEW.owner) AND (SELECT count(*) FROM key_subsidies)>=1024  BEGIN SELECT RAISE(ABORT,'accounting count capacity'); END;
CREATE TRIGGER hold_purchase_owner_insert AFTER INSERT ON payments BEGIN INSERT INTO payment_holds(kind,bucket,total)
             SELECT 'beneficiary',(CASE WHEN json_extract(NEW.record,'$.status') IN ('InFlight','Unknown') THEN json_extract(NEW.record,'$.request.beneficiary') END),(CASE WHEN json_extract(NEW.record,'$.status') IN ('InFlight','Unknown') THEN coalesce(json_extract(NEW.record,'$.credits'),0) ELSE 0 END)
             WHERE (CASE WHEN json_extract(NEW.record,'$.status') IN ('InFlight','Unknown') THEN json_extract(NEW.record,'$.request.beneficiary') END) IS NOT NULL AND (CASE WHEN json_extract(NEW.record,'$.status') IN ('InFlight','Unknown') THEN coalesce(json_extract(NEW.record,'$.credits'),0) ELSE 0 END)>0
             ON CONFLICT(kind,bucket) DO UPDATE SET total=total+excluded.total; END;
CREATE TRIGGER hold_purchase_owner_delete AFTER DELETE ON payments BEGIN UPDATE payment_holds SET total=total-(CASE WHEN json_extract(OLD.record,'$.status') IN ('InFlight','Unknown') THEN coalesce(json_extract(OLD.record,'$.credits'),0) ELSE 0 END)
             WHERE kind='beneficiary' AND bucket=(CASE WHEN json_extract(OLD.record,'$.status') IN ('InFlight','Unknown') THEN json_extract(OLD.record,'$.request.beneficiary') END) AND (CASE WHEN json_extract(OLD.record,'$.status') IN ('InFlight','Unknown') THEN coalesce(json_extract(OLD.record,'$.credits'),0) ELSE 0 END)>0;
             DELETE FROM payment_holds WHERE kind='beneficiary' AND bucket=(CASE WHEN json_extract(OLD.record,'$.status') IN ('InFlight','Unknown') THEN json_extract(OLD.record,'$.request.beneficiary') END) AND total=0; END;
CREATE TRIGGER hold_purchase_owner_update AFTER UPDATE OF record ON payments
                WHEN (CASE WHEN json_extract(OLD.record,'$.status') IN ('InFlight','Unknown') THEN json_extract(OLD.record,'$.request.beneficiary') END) IS NOT (CASE WHEN json_extract(NEW.record,'$.status') IN ('InFlight','Unknown') THEN json_extract(NEW.record,'$.request.beneficiary') END) OR (CASE WHEN json_extract(OLD.record,'$.status') IN ('InFlight','Unknown') THEN coalesce(json_extract(OLD.record,'$.credits'),0) ELSE 0 END) IS NOT (CASE WHEN json_extract(NEW.record,'$.status') IN ('InFlight','Unknown') THEN coalesce(json_extract(NEW.record,'$.credits'),0) ELSE 0 END)
                BEGIN UPDATE payment_holds SET total=total-(CASE WHEN json_extract(OLD.record,'$.status') IN ('InFlight','Unknown') THEN coalesce(json_extract(OLD.record,'$.credits'),0) ELSE 0 END)
             WHERE kind='beneficiary' AND bucket=(CASE WHEN json_extract(OLD.record,'$.status') IN ('InFlight','Unknown') THEN json_extract(OLD.record,'$.request.beneficiary') END) AND (CASE WHEN json_extract(OLD.record,'$.status') IN ('InFlight','Unknown') THEN coalesce(json_extract(OLD.record,'$.credits'),0) ELSE 0 END)>0;
             DELETE FROM payment_holds WHERE kind='beneficiary' AND bucket=(CASE WHEN json_extract(OLD.record,'$.status') IN ('InFlight','Unknown') THEN json_extract(OLD.record,'$.request.beneficiary') END) AND total=0; INSERT INTO payment_holds(kind,bucket,total)
             SELECT 'beneficiary',(CASE WHEN json_extract(NEW.record,'$.status') IN ('InFlight','Unknown') THEN json_extract(NEW.record,'$.request.beneficiary') END),(CASE WHEN json_extract(NEW.record,'$.status') IN ('InFlight','Unknown') THEN coalesce(json_extract(NEW.record,'$.credits'),0) ELSE 0 END)
             WHERE (CASE WHEN json_extract(NEW.record,'$.status') IN ('InFlight','Unknown') THEN json_extract(NEW.record,'$.request.beneficiary') END) IS NOT NULL AND (CASE WHEN json_extract(NEW.record,'$.status') IN ('InFlight','Unknown') THEN coalesce(json_extract(NEW.record,'$.credits'),0) ELSE 0 END)>0
             ON CONFLICT(kind,bucket) DO UPDATE SET total=total+excluded.total; END;
CREATE TRIGGER hold_bridge_owner_insert AFTER INSERT ON payments BEGIN INSERT INTO payment_holds(kind,bucket,total)
             SELECT 'beneficiary',(CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN json_extract(NEW.record,'$.bridge_v1.Credit.offer.vault_owner') END),(CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(NEW.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)
             WHERE (CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN json_extract(NEW.record,'$.bridge_v1.Credit.offer.vault_owner') END) IS NOT NULL AND (CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(NEW.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)>0
             ON CONFLICT(kind,bucket) DO UPDATE SET total=total+excluded.total; END;
CREATE TRIGGER hold_bridge_owner_delete AFTER DELETE ON payments BEGIN UPDATE payment_holds SET total=total-(CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(OLD.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)
             WHERE kind='beneficiary' AND bucket=(CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN json_extract(OLD.record,'$.bridge_v1.Credit.offer.vault_owner') END) AND (CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(OLD.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)>0;
             DELETE FROM payment_holds WHERE kind='beneficiary' AND bucket=(CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN json_extract(OLD.record,'$.bridge_v1.Credit.offer.vault_owner') END) AND total=0; END;
CREATE TRIGGER hold_bridge_owner_update AFTER UPDATE OF record ON payments
                WHEN (CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN json_extract(OLD.record,'$.bridge_v1.Credit.offer.vault_owner') END) IS NOT (CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN json_extract(NEW.record,'$.bridge_v1.Credit.offer.vault_owner') END) OR (CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(OLD.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END) IS NOT (CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(NEW.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)
                BEGIN UPDATE payment_holds SET total=total-(CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(OLD.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)
             WHERE kind='beneficiary' AND bucket=(CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN json_extract(OLD.record,'$.bridge_v1.Credit.offer.vault_owner') END) AND (CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(OLD.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)>0;
             DELETE FROM payment_holds WHERE kind='beneficiary' AND bucket=(CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN json_extract(OLD.record,'$.bridge_v1.Credit.offer.vault_owner') END) AND total=0; INSERT INTO payment_holds(kind,bucket,total)
             SELECT 'beneficiary',(CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN json_extract(NEW.record,'$.bridge_v1.Credit.offer.vault_owner') END),(CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(NEW.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)
             WHERE (CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN json_extract(NEW.record,'$.bridge_v1.Credit.offer.vault_owner') END) IS NOT NULL AND (CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(NEW.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)>0
             ON CONFLICT(kind,bucket) DO UPDATE SET total=total+excluded.total; END;
CREATE TRIGGER hold_bridge_prepared_insert AFTER INSERT ON payments BEGIN INSERT INTO payment_holds(kind,bucket,total)
             SELECT 'bridge_prepared',(CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN '' END),(CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(NEW.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)
             WHERE (CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN '' END) IS NOT NULL AND (CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(NEW.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)>0
             ON CONFLICT(kind,bucket) DO UPDATE SET total=total+excluded.total; END;
CREATE TRIGGER hold_bridge_prepared_delete AFTER DELETE ON payments BEGIN UPDATE payment_holds SET total=total-(CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(OLD.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)
             WHERE kind='bridge_prepared' AND bucket=(CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN '' END) AND (CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(OLD.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)>0;
             DELETE FROM payment_holds WHERE kind='bridge_prepared' AND bucket=(CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN '' END) AND total=0; END;
CREATE TRIGGER hold_bridge_prepared_update AFTER UPDATE OF record ON payments
                WHEN (CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN '' END) IS NOT (CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN '' END) OR (CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(OLD.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END) IS NOT (CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(NEW.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)
                BEGIN UPDATE payment_holds SET total=total-(CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(OLD.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)
             WHERE kind='bridge_prepared' AND bucket=(CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN '' END) AND (CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(OLD.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)>0;
             DELETE FROM payment_holds WHERE kind='bridge_prepared' AND bucket=(CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Prepared' THEN '' END) AND total=0; INSERT INTO payment_holds(kind,bucket,total)
             SELECT 'bridge_prepared',(CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN '' END),(CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(NEW.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)
             WHERE (CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN '' END) IS NOT NULL AND (CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Prepared' THEN coalesce(json_extract(NEW.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)>0
             ON CONFLICT(kind,bucket) DO UPDATE SET total=total+excluded.total; END;
CREATE TRIGGER hold_bridge_day_insert AFTER INSERT ON payments BEGIN INSERT INTO payment_holds(kind,bucket,total)
             SELECT 'bridge_day',(CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Accepted' THEN CAST(json_extract(NEW.record,'$.bridge_v1.Credit.day') AS TEXT) END),(CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Accepted' THEN coalesce(json_extract(NEW.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)
             WHERE (CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Accepted' THEN CAST(json_extract(NEW.record,'$.bridge_v1.Credit.day') AS TEXT) END) IS NOT NULL AND (CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Accepted' THEN coalesce(json_extract(NEW.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)>0
             ON CONFLICT(kind,bucket) DO UPDATE SET total=total+excluded.total; END;
CREATE TRIGGER hold_bridge_day_delete AFTER DELETE ON payments BEGIN UPDATE payment_holds SET total=total-(CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Accepted' THEN coalesce(json_extract(OLD.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)
             WHERE kind='bridge_day' AND bucket=(CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Accepted' THEN CAST(json_extract(OLD.record,'$.bridge_v1.Credit.day') AS TEXT) END) AND (CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Accepted' THEN coalesce(json_extract(OLD.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)>0;
             DELETE FROM payment_holds WHERE kind='bridge_day' AND bucket=(CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Accepted' THEN CAST(json_extract(OLD.record,'$.bridge_v1.Credit.day') AS TEXT) END) AND total=0; END;
