                WHEN (CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Accepted' THEN CAST(json_extract(OLD.record,'$.bridge_v1.Credit.day') AS TEXT) END) IS NOT (CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Accepted' THEN CAST(json_extract(NEW.record,'$.bridge_v1.Credit.day') AS TEXT) END) OR (CASE WHEN json_extract(OLD.record,'$.bridge_v1.Credit.status')='Accepted' THEN coalesce(json_extract(OLD.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END) IS NOT (CASE WHEN json_extract(NEW.record,'$.bridge_v1.Credit.status')='Accepted' THEN coalesce(json_extract(NEW.record,'$.bridge_v1.Credit.offer.amount_cycles'),0) ELSE 0 END)
